import {useQuery} from "@tanstack/react-query"
import { departamentsApi } from "@/entities/departaments/api";

export default function Locam(){

    const [data] = useQuery({
        queryFn: () => departamentsApi.getDepartaments({page: 1, pageSize: 5}),
        queryKey: ["departaments"]
    })






    return <div className="p-8 bg-background min-h-screen text-foreground">
        <h1 className="text-2xl font-bold">Локомар</h1>
        <p className="text-muted-foreground">Страница локомара</p>
    </div>
}